    [127] = {s = {["|1"] = "Talk to Behsa Alehgo at (J-7/J-8) in Eastern Adoulin at the priory (near the castle) for a cutscene.", ["|2"] = "Head to the Scouts' Coalition and talk to Wegellion at (F-9) for a cutscene.", ["|3"] = "Head to the Frontier Station at (J-8) in Yorcia Weald and talk to Emjook-Renook for a cutscene.", ["|4"] = "Emjook-Renook said he lost his Unblemished pioneer's badge at one of the following locations (J-8), (H-9), and (I-8).", ["|5"] = "Check the Suspicious Places at (J-8), (H-9), and (I-8) to obtain the Unblemished pioneer's badge.", ["|6"] = "Return to Emjook-Renook for a cutscene.", ["|7"] = "Speak with Behsa Alehgo for the final cutscene and your reward."}},
    [129] = {s = {["|1"] = "Speak with Rigobertine, Eastern Adoulin (J-7) outside the Order of Weatherspoon.", ["|2"] = "Click the Suspicious Roots at (G-6) in Yorcia Weald for a cutscene.", ["|3"] = "Select the Suspicious Roots again to enter a BCNM with a Dullahan NM, Headless Torturer.", ["|4"] = "Upon victory, examine the Suspicious Roots again for the last cutscene, and your rewards."}},
    [131] = {s = {["|1"] = "Speak with Nhili Uvolep and she will ask you to go to Dho Gates to investigate \"forces of darkness\".", ["|10"] = "The quest is technically \"completed\" at this point, as the quest is moved to the completed section of your Quests log.", ["|11"] = "Trade Nodal Wand I to Runje Desaali to initiate the next process.", ["|12"] = "Trade the following to Geosuke:", ["|13"] = "You will receive a Ripple Prominence concretion upon turning in all the items.", ["|14"] = "Trade your Nodal Wand I to the Ergon Locus at (E-10) in Dho Gates to upgrade it to the Nodal Wand II (-2% luopan damage).", ["|15"] = "Trade Nodal Wand II to Runje Desaali to initiate the next process.", ["|16"] = "Trade the following to Geosuke:", ["|17"] = "You will receive an Inferno concretion upon turning in all the items.", ["|18"] = "Trade your Nodal Wand II to the Ergon Locus at K-10 in Moh Gates to upgrade it to the Nodal Wand III (Magic Accuracy +5, Magic Atk.", ["|19"] = "Trade Nodal Wand III to Runje Desaali to initiate the next process.", ["|2"] = "Travel to (F-12) in Dho Gates (Map 1) and examine the Inlet of Whispers to receive a Rusted handbell key item.", ["|20"] = "Trade the following to Geosuke:", ["|21"] = "You will receive a Cyclone concretion upon turning in all the items.", ["|22"] = "Trade your Nodal Wand III to the Ergon Locus at K-11 in Sih Gates to obtain your new shiny Idris.", ["|23"] = "Talk to Geosuke.", ["|24"] = "Answer Yes", ["|25"] = "Trade (information needed)1,000,000 Gil to Runje Desaali and she will craft you a new Nodal Wand at the stage you were at.", ["|3"] = "Return to Nhili Uvolep.", ["|4"] = "Speak with Runje Desaali (J-11) in Eastern Adoulin.", ["|5"] = "Trade 100 High-purity Bayld to Geosuke the cute little Leafkin in Eastern Adoulin at (J-10).", ["|6"] = "You will receive the Emblazoned handbell key item.", ["|7"] = "Speak with Nhili Uvolep again.", ["|8"] = "With your main job set to GEO, examine the \"Water of Whispers\" in Dho Gates at (H-7) to enter a battlefield.", ["|9"] = "After the fight, return to Nhili Uvolep to receive your base weapon, Nodal Wand I."}},
    [132] = {s = {["|1"] = "Speak with Gaddiux at the Inventors' Coalition.", ["|11"] = "When your \"Enlightened Endeavor\" key item resonates, trade the Pickaxe to the ???.", ["|15"] = "Return to Gaddiux at the Inventors' Coalition.", ["|16"] = "Speak with Runje Desaali at (J-11) in Eastern Adoulin.", ["|17"] = "Trade 100 High-purity Bayld to Runje Desaali in Eastern Adoulin at (J-11).", ["|19"] = "You will receive the Vial of crimson catalyst key item.", ["|20"] = "Speak with Octavien at (I-8) in Eastern Adoulin until he talks about the Vial of crimson catalyst.", ["|21"] = "Travel to Rala Waterways (M-6) from Eastern Adoulin (F-7) and examine the door behind Yeggha Dolashi.", ["|22"] = "There is a 15 minute time limit.", ["|23"] = "You will fence against Zurko-Bazurko.", ["|24"] = "Zurko will dual wield swords and have access to normal sword weapon skills as well as Savage Blade and Chant du Cygne.", ["|25"] = "Casts Protect IV, Shell V, and Phalanx exclusively.", ["|26"] = "Frequently parries which will limit your physical damage leaving Swipe and Lunge as effective options.", ["|27"] = "Zurko-Bazurko will use Lunge which can do significant damage if no opposing runes are active.", ["|29"] = "(Optional) Return to Octavien for a short dialogue directing you to the Order of Orvail's maester.", ["|30"] = "Speak with Gaddiux in Western Adoulin (J-10) for a cutscene with Amchuchu and to receive your base weapon, Lexeme Blade I.", ["|32"] = "Trade your Lexeme Blade I to Runje Desaali", ["|33"] = "Then trade her the following:", ["|4"] = "Obtain a Pickaxe, you will only need one.", ["|41"] = "You will receive Superlative runic ring of deluge.", ["|42"] = "Trade your Lexeme Blade I to the Runic Overflow at (K-10) in Foret de Hennetiel (Biv #2) to upgrade to Lexeme Blade II (DMG:228 PDT II -2%).", ["|43"] = "Trade your Lexeme Blade II to Runje Desaali", ["|44"] = "Then trade her the following:", ["|52"] = "You will receive Superlative runic ring of luster.", ["|53"] = "Trade your Lexeme Blade II to the Runic Overflow at (I-12) in Marjami Ravine (Biv #2) to upgrade to Lexeme Blade III (DMG:231 Enmity+10 PDT", ["|54"] = "Trade your Lexeme Blade III to Runje Desaali", ["|55"] = "Then trade her the following:", ["|61"] = "You will receive Superlative runic ring of vision.", ["|62"] = "Trade your Lexeme Blade III to the Runic Overflow on top of the barrel in Western Adoulin at (I-10) to obtain your shiny new Epeolatry.", ["|64"] = "Talk to Geosuke.", ["|65"] = "Answer Yes", ["|66"] = "Trade (information needed)1,000,000 Gil to Runje Desaali and she will craft you a new Lexeme Blade at the stage you were at.", ["|7"] = "Head to (I-8) in Yorcia Weald and examine the ???."}},
    [136] = {s = {["|1"] = "Zone into Western Adoulin from Ceizak Battlegrounds for a cutscene.", ["|2"] = "Check the Occultist Footprints at the west side of (J-6) in Yorcia Weald, north from the Frontier Station to receive Sturdy hide pouch.", ["|3"] = "Visit the following Ergon Locus in any order:", ["|4"] = "Zone into Cirdas Caverns for a cutscene.", ["|5"] = "Check the Hiding Place at the southeast corner of (K-7) for a cutscene and your reward."}},
    [138] = {s = {["|1"] = "Talk to Estelle (F-9) in Eastern Adoulin behind the Scout Coalition building.", ["|10"] = "Return to the crate at Eastern Adoulin (I-9) for a cutscene.", ["|11"] = "Talk to Estelle (F-9) for your reward.", ["|12"] = "Go to Foret de Hennetiel (F-7) and select the ??? (from bivouac #4, go to G-7; at G-7, examine the Castoff Point, select \"Yes\" when asked", ["|13"] = "Go to Selbina and board (for 100 gil) the ferry bound for Mhaura.", ["|2"] = "Check the ??? in the crates in the alcove next to the base of the ramp at (I-9) for a cutscene.", ["|3"] = "Talk to Chumli-Mojumli (K-10) and ask for Estienneux.", ["|4"] = "Talk to Mastan (G-6) in Western Adoulin.", ["|5"] = "Return to the crate at Eastern Adoulin (I-9) for a cutscene.", ["|6"] = "Go to Rala Waterways (H-6) and check the Storage Container for a cutscene.", ["|7"] = "You have to answer 2 questions right in the cutscene to continue, the answers are:", ["|8"] = "Arciela.", ["|9"] = "Morimar."}},
    [142] = {s = {["|1"] = "Speak to Sylvie at Western Adoulin Waterfront (I-5) Waypoint #9 as Geomancer to begin the quest.", ["|10"] = "Your reward is a random assortment of 3 of the following items: Fiendish Skin, Siren's Hair, Arachne Thread, Khroma Ore and Star Sapphire.", ["|11"] = "Go to the Crag of Mea (I-6) in Tahrongi Canyon and check the Ergon Locus ??? underneath the Telepoint.", ["|12"] = "This is a solo fight for Geomancers only.", ["|13"] = "Your enemy for this fight is the Content Level 135 version of Otherworldly Rimester, a Ghost.", ["|14"] = "The Rimester has access to numerous Bard songs, including Horde Lullaby II, Dragonfoe Mambo, Magic Finale, Massacre Elegy, Valor Minuet V,", ["|15"] = "Rimester's TP moves are Dark Sphere, Fear Touch, Ectosmash and Terror Touch.", ["|16"] = "The Rimester has a shifting elemental vulnerability, but the pattern behind the shifts is currently unknown.", ["|17"] = "Your reward is 1 Codex of Etchings and a random assortment of 10 of the following items: Fiendish Skin, Siren's Hair, Arachne Thread,", ["|18"] = "If you fail, you must return to Sylvie for a new Mea crystal of flames.", ["|19"] = "Return to Sylvie.", ["|2"] = "Go to Morimar Basalt Fields (J-6) northeast of bivouac #2 and check the Ergon Locus ??? for a cutscene.", ["|20"] = "Talk to Wescolina (H-7).", ["|21"] = "Talk to Helina (H-9), located inside the Weaver's Guild in Selbina.", ["|22"] = "Wait until the next game day, then talk to Helina for your reward: 15000 XP and Azimuth Coat.", ["|23"] = "To repeat the quest fight after successful completion, speak to Sylvie to receive a new Key Item once per Conquest Tally.", ["|24"] = "Speak to Helina in Selbina to commission additional armor pieces.", ["|25"] = "You have the option to either bring certain materials to her, or an amount of H-P Bayld.", ["|26"] = "After turning in the items to her for a piece, you are given a temporary key item order slip.", ["|3"] = "Go to (G/H-7) and ascend the Scalable Area near the NW side of the Hot Spring.", ["|4"] = "Return to Sylvie.", ["|5"] = "Go to the Crag of Holla (K-8) in La Theine Plateau and check the Ergon Locus ??? underneath the Telepoint.", ["|6"] = "This is a solo fight.", ["|7"] = "Your enemy for this fight is Otherworldly Rimester, a Ghost.", ["|8"] = "Upon defeating Otherworldly Rimester you will earn 10000 bayld and Pale azure cloth.", ["|9"] = "Go to the Crag of Dem (I-6) in Konschtat Highlands and check the Ergon Locus ??? underneath the Telepoint."}},
    [143] = {s = {["|1"] = "Speak to Octavernost (K-9) near the Big Bridge waypoint in Western Adoulin as a Rune Fencer.", ["|10"] = "Head to (E-7) to cross back over to Map 1.", ["|11"] = "Go to (G-6) and examine the Hazy Rune behind the Strange Apparatus.", ["|12"] = "It has very low HP, but will cast dispelga and various single target elemental magic tier IV-VI.", ["|13"] = "After defeating Arcus Blades you will earn 3 synthesis materials related to the Erilaz Armor Set.", ["|14"] = "Proceed to the \"Afterwards\" section below.", ["|15"] = "Make your way to the Strange Apparatus in Ranguemont Pass.", ["|16"] = "Examine the Hazy Rune behind the Strange Apparatus.", ["|17"] = "You may not summon Trusts to assist you.", ["|18"] = "You must be on RUN for this fight.", ["|19"] = "It has very low HP, but will cast dispelga and various single target elemental magic tier IV-VI.", ["|2"] = "Head to Outer Ra'Kaznar (M-6) and check the Meeting Point for a cutscene and to receive a Refined Ra'Kaznar fiber key item.", ["|20"] = "After defeating Arcus Blades you will earn 10 synthesis materials related to the Erilaz Armor Set and a Codex of Etchings.", ["|21"] = "You also earn the title Sword Saint and Octavernost will address you as such.", ["|22"] = "Proceed to the \"Afterwards\" section below.", ["|23"] = "Optional: Return to Octavernost at the Big Bridge who instructs you to proceed to Amchuchu.", ["|24"] = "Check Amchuchu's Laboratory at the Inventor's Coalition in Western Adoulin (J-10) for a cutsene.", ["|25"] = "Wait one game day and then talk to Octavernost for your reward of 15000 XP and an Erilaz Surcoat!", ["|26"] = "You may speak to Octavernost afterwards to request another KI to repeat a fight.", ["|27"] = "After receiving your Surcoat you may immediately speak with Octavernost to begin forging the rest of the Erilaz Armor Set.", ["|28"] = "He will ask for different ingredients for each piece of armor; after trading the ingredients he will give you a Order slip for the armor.", ["|29"] = "You can acquire another Erilaz Surcoat if you tossed the other one.", ["|3"] = "Return to Octavernost.", ["|4"] = "Head to King Ranperre's Tomb (H-10) and examine the ??? in the middle of the concrete slab to enter Map 2.", ["|5"] = "Then proceed along the right wall to the NW corner (E-8) and run through the fake wall.", ["|6"] = "It has very low HP, but will cast dispelga and various single target elemental magic tier IV-VI.", ["|7"] = "After defeating Arcus Blades you will earn 10,000 Bayld, and your Refined Ra'Kaznar fiber will transform into an Arcus fiber.", ["|8"] = "Proceed to the \"Afterwards\" section below.", ["|9"] = "Proceed to Fei'Yin (G-9) to cross over to Map 2."}},
    [144] = {s = {["|1"] = "Speak with Levil in the Pioneers' Coalition (E-8) for a cutscene to begin the Quest.", ["|10"] = "Upon defeating Siren, a cutscene will begin where you will be able to choose your reward.", ["|11"] = "See also: Testimonial Discussion Page.", ["|2"] = "Speak with Ploh Trishbahk at (K-9) in Eastern Adoulin for another cutscene.", ["|3"] = "Go to Escha - Ru'Aun and examine the blue ??? at (H-10) at the top of the stairs to the left of the entrance for a cutscence.", ["|4"] = "Return to Ploh Trishbahk for another cutscene.", ["|5"] = "Meet Arciela, Ygnas, and Darrcuiln in Kamihr Drifts at (H-5), and examine the Alpine Trail for a cutscene.", ["|6"] = "Venture to the Crag closest to your home Nation (current allegiance, not starting nation) and click the Ergon Locus ??? located beneath the", ["|7"] = "Enter Leafallia for a cutscene.", ["|8"] = "Examine the glowing spot Drifting Feather at (H-7) for another cutscene.", ["|9"] = "Examine the Drifting Feather again to enter a BCNM."}},
}
